const previousConceptNotes={
pitch:'A research team excavates a colossal, living egg perched above a chasm in the distorted Backrooms, selling discoveries to fund exotic tools and scaffolding while risking the attention of whatever breathes inside.',
loop:'Start the workday at the encampment → cross the company-provided landing → crack away the egg’s outer junk → collect resources and uncover mysteries → return to the automated selling machinery → spend cash on upgraded exotic utilities → craft scaffolding to reach new surfaces → push deeper on the next expedition.\n\nAlong the way: uncover riches, hidden doors, and other Backrooms areas. Excavation can agitate the egg and cause abnormalities to spawn.',
world:'A huge chasm cuts through the distorted Backrooms. An egg-like mass is perched above the canyon, initially coated in junk. The company provides the first landing; the research team builds additional scaffolding.\n\nThe encampment sits near a bright room, with automated machinery for selling resources. Beyond the worksite, exploration leads to other wonders. The egg is not inert: something inside is hidden, breathing, and watching.\n\nVisual reference: the supplied concept art contrasts yellow fluorescent rooms with exposed teal, red, and violet interiors surrounding the central egg and precarious walkways.',
mechanics:'Established premise\n• Remove the junk outer layer of the egg.\n• Collect resources and sell them for cash at automated camp machinery.\n• Upgrade an assortment of exotic utilities.\n• Craft scaffolding to reach new parts of the egg.\n• Discover riches and concealed doors into other areas.\n• Work within a standard workday.\n• Excessive agitation may spawn abnormalities.\n\nPrototype proposal\nBegin with one tool, one removable junk patch, one sellable resource, one upgrade, one scaffold segment, and one anomaly. This is a suggested first slice, not a fixed final scope.',
decisions:'Established direction\n• Working title: In to the Crackrooms.\n• The central mystery is a living egg above a chasm.\n• Start excavation at the outer layer of junk.\n• Use resource sales to fund tools and further exploration.\n• The company supplies initial access; the team extends it with scaffolding.\n• Maintain an encampment near a bright room.\n\nStill to decide\nEngine, team size and co-op implementation, workday rules, resource values, building rules, and the consequences of failure.',
questions:'What is inside the egg, and how much should players learn at each layer?\nWhat causes agitation: tool impact, noise, excavation depth, time, or something else?\nHow does the egg warn the team before an abnormality appears?\nWhat makes each exotic utility useful beyond removing junk faster?\nHow are scaffolds supported, placed, and paid for?\nWhat ends a workday, and what happens if the team stays out?\nWhat role does the bright room play?\nHow does a hidden-door expedition connect back to the egg?\nWhat is the intended player count and cooperation model?'
};
const previousConceptNext='Prototype one complete trip: reach the egg, remove junk, collect a resource, return to camp, and sell it.';
const conceptNotes={
pitch:'A research team excavates a colossal, living sphere known as the egg, perched above a chasm in the distorted Backrooms, selling discoveries to fund exotic tools and scaffolding while risking the attention of whatever breathes inside.',
loop:'Wake in an enclosed Backrooms room in the starting area → enter an antechamber → press the button to open the safety door into the greater egg chamber → cross the company-provided landing → excavate scraps of junk and Backrooms remnants → collect resources and discoveries → deposit the haul at the chamber’s collection system for cash → buy equipment and upgrades at the chamber store → build scaffolding and explore further.\n\nAlong the way: uncover riches, hidden doors, and other Backrooms areas. Excavation can agitate the egg and cause abnormalities to spawn.',
world:'A huge chasm cuts through the distorted Backrooms. A roughly spherical mass, still called the egg, is perched above the canyon. Its outer shell is almost entirely scraps of junk and Backrooms remnants. Deeper excavation gradually reveals living qualities and connections between realities; the exact nature of its core remains a mystery. The company provides the first landing; the research team builds additional scaffolding.\n\nThe camp is the starting spot. The current starting-area idea is a set of enclosed Backrooms rooms: the player wakes in one, reaches an antechamber, and presses a button to open a safety door into the greater egg chamber. The chamber itself contains a collection deposit system that pays cash and an equipment store. Other facilities remain to be defined. Beyond the worksite, exploration leads to other wonders. The egg is not inert: something inside is hidden, breathing, and watching.\n\nVisual reference: the supplied concept art contrasts yellow fluorescent rooms with exposed teal, red, and violet interiors surrounding the central egg and precarious walkways.',
mechanics:'Established premise\n• Wake in the starting area and open the antechamber safety door with a button.\n• Remove an outer shell of junk and Backrooms remnants from the spherical egg.\n• Deposit collected resources for cash inside the egg chamber.\n• Buy equipment and upgraded exotic utilities at the chamber store.\n• Craft scaffolding to reach new parts of the egg.\n• Discover riches and concealed doors into other areas.\n• Work within a standard workday.\n• Excessive agitation may spawn abnormalities.\n\nPrototype proposal\nBegin with one tool, one removable junk patch, one sellable resource, one upgrade, one scaffold segment, and one anomaly. This is a suggested first slice, not a fixed final scope.',
decisions:'Established direction\n• Working title: In to the Crackrooms.\n• The egg is currently envisioned as a sphere above a chasm.\n• Unpacking it gradually combines mystery, living qualities, and connections between realities.\n• Start excavation at the outer layer of junk.\n• Use resource sales to fund tools and further exploration.\n• The company supplies initial access; the team extends it with scaffolding.\n• Treat the camp as the starting spot.\n• Proposed entrance: enclosed waking room → antechamber → button-operated safety door → greater egg chamber.\n• Locate the resource deposit system and equipment store inside the egg chamber.\n\nStill to decide\nEngine, team size and co-op implementation, workday rules, resource values, building rules, and the consequences of failure.',
questions:'What is inside the egg, and how much should players learn at each layer?\nWhat causes agitation: tool impact, noise, excavation depth, time, or something else?\nHow does the egg warn the team before an abnormality appears?\nWhat makes each exotic utility useful beyond removing junk faster?\nHow are scaffolds supported, placed, and paid for?\nWhat ends a workday, and what happens if the team stays out?\nHow are the starting rooms arranged, and what role does the previously mentioned bright room play?\nWhat other facilities belong inside the egg chamber?\nHow does a hidden-door expedition connect back to the egg?\nWhat is the intended player count and cooperation model?'
};
let conceptNext='Prototype the opening route: wake in a room, cross the antechamber, open the safety door, excavate junk, deposit resources, and buy equipment inside the egg chamber.';
// Revision-two defaults are retained to upgrade untouched browser notes safely.
const revisionTwoNotes={...conceptNotes};
const economyTasks=[
 'Route every resource payout and store purchase through one shared team cash pool',
 'Reset all items purchased for the day each morning and test the day transition'
];
phases[1].tasks.push(...economyTasks);
conceptNotes.loop='Morning: all items purchased for the previous day reset → wake in the starting room → pass through the antechamber and open the safety door → enter the greater egg chamber → check the shared team funds and choose purchases for the day at the chamber store → excavate and collect resources → deposit the haul at the collection system into one shared cash pool → spend together on equipment for the remaining shift or hold the money → extend access and explore → repeat when the next morning resets daily purchases.\n\nResource rewards belong to the team, not individual players. Daily purchases provide capability for the current day. Cash carryover, starting equipment, and the persistence of scaffolding, excavation, and discoveries remain undecided.';
conceptNotes.mechanics+='\n\nCore economy rules — decided November 4, 2026\n• All items purchased for the day reset each morning.\n• Resource payouts go into one shared team cash pool instead of individual player rewards.\n• Store purchases draw from the shared team pool.\n• The item reset does not yet define what happens to unspent cash, scaffolding, or world progress.';
conceptNotes.decisions+='\n\nConfirmed November 4, 2026\n• Daily purchases reset each morning; they are not a permanent accumulation of purchased gear.\n• Players share one cash pool rather than earning separate individual payouts.\n\nOpen economy decisions\nCash carryover, starting funds or baseline tools, who may authorize spending, and the treatment of purchased building materials versus placed scaffolding.';
conceptNotes.questions+='\nDoes unspent shared cash carry over to the next morning?\nWhat baseline tools or funds prevent a team with no cash from becoming unable to work?\nCan any player spend shared funds, or do purchases need team approval?\nDoes placed scaffolding persist after purchased items reset?\nWhich excavation changes, discoveries, and unlocks persist between days?\nHow does a late-day purchase justify its cost before the morning reset?';
const eggDefaults={
 shell:'Established direction: the egg is probably spherical. Its outer shell is almost entirely scraps of junk and Backrooms remnants.\n\nDiscuss the component mix: broken furnishings, fragments of rooms, architectural pieces, and useful salvage. Which materials are common? Which require a special utility? What does each component yield?',
 layers:'Established direction: unpacking the egg should gradually combine all three aspects — an unresolved mystery, a living presence, and connections between realities.\n\nWorking reveal sequence (proposal):\n1. Familiar junk and Backrooms remnants suggest a salvage operation.\n2. Strange arrangements and breathing cues make the debris feel less accidental.\n3. Embedded spaces or hidden doors reveal connections to other areas.\n4. Deeper evidence connects those discoveries to whatever lies at the core.\n\nThe number of layers, their materials, and the order of reveals are still open.',
 core:'The research team is trying to uncover what the egg is and what is hidden at its center. The answer can involve both a living presence and a connection between realities; these do not need to be separate explanations.\n\nStill to determine: What are we physically searching for? Is there a recoverable object, an encounter, a passage, or a discovery rather than a prize? Why does the company want access? What evidence lets players revise their understanding? What happens if they finally reach it?',
 discoveries:'Established rewards: riches and resources that fund further adventure, hidden doors into other Backrooms areas, and mysteries to unpack.\n\nDefine each discovery by: component or layer / clue before exposure / interaction required / reward or destination / effect on the egg.\n\nKeep the outer shell mostly junk; let meaningful finds and impossible connections emerge as it is unpacked.',
 agitation:'Established behavior: something inside is breathing and watching. Agitate the egg too much and abnormalities may spawn.\n\nDesign questions: Which actions cause agitation? Is the response local or global? Does it decay? How do breathing, movement, sound, or lighting warn the team? Can players deliberately risk a response for a better discovery?\n\nSuggested structure to discuss: disturbance → readable warning → escalation → manifestation → recovery. Thresholds and rules are not decided.',
 spawns:'No spawn roster is confirmed yet. Candidate behaviors to discuss:\n\nSCRAP CRAWLER — junk pulls itself together into a mobile threat. Possible warning: nearby debris shifts before assembly. Question: can the team interrupt it or must they retreat?\n\nWATCHER — a presence appears in an exposed room and reacts to continued excavation. Possible warning: a silhouette or repeated visual cue. Question: what readable rule makes it threatening without feeling arbitrary?\n\nFALSE OPENING — a temporary spatial abnormality resembles a newly uncovered doorway. Possible warning: a mismatch in sound or geometry. Question: how can players distinguish a real discovery from a hazardous one?\n\nFor each selected spawn, define trigger, warning, location, behavior, counterplay, duration, and reward or consequence. These are proposals, not established lore.'
};
const eggPrompts={shell:['Glass shell & components','What can the team collect, fracture, and research?'],layers:['Seven-stage excavation','Track each layer, its obstacle, and the tool that opens the next stage.'],core:['The core & what we seek','What are we trying to reach, recover, understand, or release?'],discoveries:['Discoveries & embedded spaces','Connect resources, clues, and hidden doors to the layers.'],agitation:['Agitation & warning signals','Define how the egg reacts before a spawn appears.'],spawns:['Spawn catalogue & counterplay','Develop possible abnormalities and how players can respond.']};
const revisionThreeNotes={...conceptNotes};
const revisionThreeEgg={...eggDefaults};
const revisionThreeNext=conceptNext;
Object.assign(conceptNotes,currentDesign.notes);
Object.assign(eggDefaults,currentDesign.egg);
conceptNext=currentDesign.next;
const glassTaskChanges=[['Build movement and a basic tool that removes outer junk','Build movement and a basic tool that cracks the glass exterior'],['Collect the first resources from an excavated patch','Collect the first glass resources from an excavated patch']];
for(const [oldTitle,newTitle] of glassTaskChanges){for(const phase of phases)phase.tasks=phase.tasks.map(title=>title===oldTitle?newTitle:title);}
for(const [title,phase] of currentDesign.buildTasks)phases[phase].tasks.push(title);
const makePlayerRoadmap=()=>currentDesign.roadmap.map(stage=>({...stage,bullets:[...stage.bullets]}));
const previousTaskTitles=['Block out the chasm, egg, landing, and nearby encampment','Build the automated resource-selling machine at camp','Buy and test the first exotic utility upgrade','Prototype a workday from departure to return and sale'];
function migrateEarlierConcept(s){
 if(!s.egg)s.egg={...eggDefaults};
 if(s.contentRevision>=2)return s;
 if(!(s.contentRevision>=1)){
  if(s.project.name==='BackroomsLore')s.project.name='In to the Crackrooms';
  if(s.project.tagline==='A game-building journey, one experiment at a time.')s.project.tagline='Excavate the impossible. Fund the next descent. Learn what is watching.';
  for(const [key,value] of Object.entries(conceptNotes))if(!s.notes[key].trim())s.notes[key]=value;
  if(!s.next.trim())s.next=conceptNext;
  const defaults=phases.flatMap((p,phase)=>p.tasks.slice(0,3).map(title=>({title,phase})));
  for(const task of s.tasks){const index=legacyTasks.indexOf(task.title);if(index>=0&&!task.done){task.title=defaults[index].title;task.phase=defaults[index].phase;}}
  for(const task of defaults)if(!s.tasks.some(t=>t.title===task.title))s.tasks.push({id:uid(),...task,done:false});
 }else{
  for(const key of Object.keys(conceptNotes))if(s.notes[key]===previousConceptNotes[key])s.notes[key]=conceptNotes[key];
  if(s.next===previousConceptNext)s.next=conceptNext;
  const replacements=[phases[0].tasks[0],...phases[1].tasks];
  for(const task of [...s.tasks]){const index=previousTaskTitles.indexOf(task.title);if(index<0)continue;if(!task.done)task.title=replacements[index];else if(!s.tasks.some(t=>t.title===replacements[index]))s.tasks.push({id:uid(),title:replacements[index],phase:index===0?0:1,done:false});}
 }
 const entrance=phases[0].tasks[3];if(!s.tasks.some(t=>t.title===entrance))s.tasks.push({id:uid(),title:entrance,phase:0,done:false});
 s.contentRevision=2;
 return s;
}
function migrateEconomyConcept(s){
 migrateEarlierConcept(s);
 if(s.contentRevision>=3)return s;
 for(const key of Object.keys(revisionTwoNotes)){
  if(s.notes[key]===revisionTwoNotes[key])s.notes[key]=conceptNotes[key];
 }
 for(const title of economyTasks)if(!s.tasks.some(t=>t.title===title))s.tasks.push({id:uid(),title,phase:1,done:false});
 s.contentRevision=3;
 return s;
}
function migrateGlassConcept(s){
 migrateEconomyConcept(s);
 if(!s.playerRoadmap)s.playerRoadmap=makePlayerRoadmap();
 if(s.contentRevision>=4)return s;
 for(const key of Object.keys(revisionThreeNotes))if(s.notes[key]===revisionThreeNotes[key])s.notes[key]=conceptNotes[key];
 for(const key of Object.keys(revisionThreeEgg))if(s.egg[key]===revisionThreeEgg[key])s.egg[key]=eggDefaults[key];
 if(s.next===revisionThreeNext)s.next=conceptNext;
 for(const [oldTitle,newTitle] of glassTaskChanges){for(const task of [...s.tasks])if(task.title===oldTitle){if(!task.done)task.title=newTitle;else if(!s.tasks.some(t=>t.title===newTitle))s.tasks.push({id:uid(),title:newTitle,phase:task.phase,done:false});}}
 for(const [title,phase] of currentDesign.buildTasks)if(!s.tasks.some(t=>t.title===title))s.tasks.push({id:uid(),title,phase,done:false});
 s.contentRevision=4;
 return s;
}
function migrateConcept(s){
 migrateGlassConcept(s);
 if(s.contentRevision>=5)return s;
 for(const key of Object.keys(revisionFourDesign.notes))if(s.notes[key]===revisionFourDesign.notes[key])s.notes[key]=conceptNotes[key];
 for(const key of Object.keys(revisionFourDesign.egg))if(s.egg[key]===revisionFourDesign.egg[key])s.egg[key]=eggDefaults[key];
 if(s.next===revisionFourDesign.next)s.next=conceptNext;
 // Replace only the untouched old plan. Customized plans stay editable beside the canonical table.
 if(sameRoadmap(s.playerRoadmap,revisionFourDesign.roadmap))s.playerRoadmap=makePlayerRoadmap();
 s.contentRevision=5;
 return s;
}
function sameRoadmap(a,b){return a.length===b.length&&a.every((stage,i)=>stage.id===b[i].id&&stage.title===b[i].title&&stage.unlock===b[i].unlock&&JSON.stringify(stage.bullets)===JSON.stringify(b[i].bullets));}
function validPlayerRoadmap(stages){
 if(!Array.isArray(stages)||stages.length>100)return false;
 const ids=new Set();
 return stages.every(s=>s&&typeof s.id==='string'&&!ids.has(s.id)&&ids.add(s.id)&&typeof s.title==='string'&&typeof s.unlock==='string'&&Array.isArray(s.bullets)&&s.bullets.length<=100&&s.bullets.every(b=>typeof b==='string'));
}
const prompts={pitch:['The game in one sentence','What does the player do, and why does it matter?','A player…'],loop:['Core gameplay loop','What will players do again and again?','Explore → discover → decide → …'],world:['World & atmosphere','Capture locations, lore, mood, and visual direction.','What should this world feel like?'],mechanics:['Mechanics & experiments','Keep hypotheses, rules, and things to try.','I want to test whether…'],decisions:['Decisions & trade-offs','Remember what you chose and why.','Decision / reason / what I gave up…'],questions:['Open questions','Give uncertainties a place to live.','What do I need to figure out next?']};
const uid=()=>crypto.randomUUID();
const dateValue=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
function initial(){return {version:1,contentRevision:5,playerRoadmap:makePlayerRoadmap(),egg:{...eggDefaults},project:{name:'In to the Crackrooms',tagline:'Excavate the impossible. Fund the next descent. Learn what is watching.'},next:conceptNext,notes:{...conceptNotes},entries:[],tasks:phases.flatMap((p,phase)=>p.tasks.map(title=>({id:uid(),title,phase,done:false}))),updatedAt:null};}
let state=initial(),saveError=false,view='overview',query='',kind='all',toastTimer,submitHandler;
function validate(s){if(!s||s.version!==1||typeof s.project?.name!=='string'||!s.project.name.trim()||typeof s.project.tagline!=='string'||typeof s.next!=='string'||!s.notes||!Array.isArray(s.entries)||!Array.isArray(s.tasks))return false;if(s.playerRoadmap!==undefined&&!validPlayerRoadmap(s.playerRoadmap))return false;if(s.egg!==undefined&&(!s.egg||!Object.keys(eggDefaults).every(k=>typeof s.egg[k]==='string')))return false;if(!Object.keys(prompts).every(k=>typeof s.notes[k]==='string'))return false;if(s.entries.length>10000||s.tasks.length>10000)return false;const dateOK=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(Date.parse(v+'T12:00:00'));const ids=new Set();return s.entries.every(e=>typeof e.id==='string'&&!ids.has(e.id)&&ids.add(e.id)&&['title','body','lesson','next','type'].every(k=>typeof e[k]==='string')&&dateOK(e.date)&&Number.isFinite(e.minutes)&&e.minutes>=0&&e.minutes<=1440&&['Build','Design','Research','Playtest'].includes(e.type))&&s.tasks.every(t=>typeof t.id==='string'&&!ids.has(t.id)&&ids.add(t.id)&&typeof t.title==='string'&&typeof t.done==='boolean'&&Number.isInteger(t.phase)&&t.phase>=0&&t.phase<4);}
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(!validate(parsed))throw new Error('Invalid saved data');state=migrateConcept(parsed);if(!parsed.updatedAt||parsed.contentRevision!==JSON.parse(raw).contentRevision)localStorage.setItem(KEY,JSON.stringify(state));}}catch(e){saveError=true;}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s);
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function save(){state.updatedAt=new Date().toISOString();try{localStorage.setItem(KEY,JSON.stringify(state));saveError=false;$('#save-state').textContent='● Saved on this device';return true;}catch(e){saveError=true;$('#save-state').textContent='! Not saved — export a backup';toast('Browser storage is unavailable or full. Export a backup to keep your work.');return false;}}
function formattedDate(d){return new Date(d+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});}
function sortedEntries(){return [...state.entries].sort((a,b)=>b.date.localeCompare(a.date)||String(b.createdAt||'').localeCompare(String(a.createdAt||'')));}
const done=()=>state.tasks.filter(t=>t.done).length;
const percent=()=>state.tasks.length?Math.round(done()/state.tasks.length*100):0;
function heading(kicker,title,description,action=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
const addEntryButton='<button class="button" data-action="new-entry">+ &nbsp; Log a session</button>';
function taskHTML(t){return `<div class="task-row ${t.done?'done':''}"><input class="task-check" type="checkbox" id="task-${esc(t.id)}" data-task="${esc(t.id)}" ${t.done?'checked':''}><label for="task-${esc(t.id)}">${esc(t.title)}</label><button class="icon-button" data-action="edit-task" data-id="${esc(t.id)}" aria-label="Edit ${esc(t.title)}">⋯</button></div>`;}
function entryHTML(e,compact=false){return `<article class="entry"><div class="entry-top"><div class="entry-meta"><span class="tag">${esc(e.type)}</span> ${formattedDate(e.date)}${e.minutes?' · '+e.minutes+' MIN':''}</div><div><button class="icon-button" data-action="edit-entry" data-id="${esc(e.id)}" aria-label="Edit ${esc(e.title)}">↗</button>${compact?'':`<button class="icon-button" data-action="delete-entry" data-id="${esc(e.id)}" aria-label="Delete ${esc(e.title)}">×</button>`}</div></div><h3>${esc(e.title)}</h3><div class="entry-body">${esc(compact&&e.body.length>180?e.body.slice(0,180)+'…':e.body)}</div>${!compact&&e.lesson?`<div class="entry-detail"><b>WHAT I LEARNED</b>${esc(e.lesson)}</div>`:''}${!compact&&e.next?`<div class="entry-detail"><b>NEXT STEP</b>${esc(e.next)}</div>`:''}</article>`;}
function emptyJournal(){return `<div class="card empty"><div class="empty-symbol">↳</div><h3>The first page is yours.</h3><p>Built a mechanic? Found an idea? Got stuck?<br>Every part of the process is worth recording.</p><button class="button secondary" data-action="new-entry">Write your first entry ↗</button></div>`;}
function overview(){const totalMinutes=state.entries.reduce((sum,e)=>sum+e.minutes,0),hours=Math.round(totalMinutes/60*10)/10;const pending=state.tasks.filter(t=>!t.done).slice(0,3);return heading('YOUR LIVING PROJECT DOCUMENT',esc(state.project.name),esc(state.project.tagline),addEntryButton)+`<figure class="concept-banner"><a href="assets/egg-glass-tissue-concept.png" target="_blank" rel="noopener" aria-label="Open the full In to the Crackrooms concept artwork"><img src="assets/egg-glass-tissue-concept.png" alt="Research crew overlooking a vast chasm in the Backrooms, with a spherical glass shell, soft tissue center, embedded glitched objects, and an event doorway." width="1672" height="941"></a><figcaption><span>EARLIER STUDY / GLASS & TISSUE</span><a href="#vision">Explore the game vision ↗</a></figcaption></figure><section class="expedition-intro"><div><div class="eyebrow">THE CENTRAL MYSTERY</div><h2>Break the glass.<br>Something inside is watching.</h2></div><div><p>A research team. An impossible egg above a chasm. Every layer promises resources, hidden doors, and another reason to keep digging.</p><a href="#vision" class="button secondary">Open the expedition brief ↗</a></div></section><div class="stats"><div class="stat"><div class="stat-label">Sessions documented</div><div class="stat-value">${String(state.entries.length).padStart(2,'0')}<small>entries</small></div></div><div class="stat"><div class="stat-label">Time invested</div><div class="stat-value">${hours}<small>hours logged</small></div></div><div class="stat"><div class="stat-label">Milestone tasks</div><div class="stat-value">${done()}<small>/ ${state.tasks.length} complete</small></div></div><div class="stat"><div class="stat-label">Your roadmap</div><div class="stat-value">${percent()}<small>% complete</small></div></div></div><div class="two-column"><section><div class="section-heading"><h3>Latest fieldnotes</h3><a href="#journal">View all entries ↗</a></div>${state.entries.length?sortedEntries().slice(0,2).map(e=>entryHTML(e,true)).join(''):emptyJournal()}</section><section><div class="section-heading"><h3>A little direction</h3><a href="#roadmap">Open milestones ↗</a></div><div class="card">${pending.length?pending.map(taskHTML).join(''):'<h3>Your roadmap is complete.</h3><p class="muted small">Make space for the next chapter by adding a new milestone task.</p>'}<div class="progress-label"><span>Progress, at your pace</span><span>${percent()}%</span></div><div class="progress"><div style="width:${percent()}%"></div></div></div><div class="card prompt-card" style="margin-top:18px"><div class="eyebrow">A NOTE TO FUTURE YOU</div><h3>Where will you pick up?</h3><p class="small muted">Leave yourself one clear next step.</p><label for="next-step" class="sr-only">Next session focus</label><textarea id="next-step" class="next-input" placeholder="Next time, I want to…" maxlength="10000">${esc(state.next)}</textarea></div></section></div>`;}
function conceptFigure(){return `<figure class="concept-banner"><a href="assets/egg-glass-tissue-concept.png" target="_blank" rel="noopener" aria-label="Open glass and tissue egg concept art"><img src="assets/egg-glass-tissue-concept.png" width="1672" height="941" alt="Cutaway concept of a glass-shelled sphere with soft tissue, glitched everyday objects being realified, and an embedded door in a wide Backrooms maze chamber."></a><figcaption><span>CONCEPT 003 / GLASS · TISSUE · GLITCHED REALITY</span><span>Earlier material study · intermediate layers not pictured</span></figcaption></figure>`;}
function vision(){return heading('02 / THE EXPEDITION BRIEF','Arrive. Excavate. Find a way out.','Current direction · November 5, 2026')+conceptFigure()+`
<div class="vision-lead"><span class="eyebrow">IN TO THE CRACKROOMS</span><h2>The chamber is the center.<br>The maze is never empty.</h2><p>${esc(conceptNotes.pitch)}</p></div>
<div class="vision-grid">
<section class="card"><span class="phase-no">01 / ARRIVAL & SPACE</span><h3>A go-kart ride into the workday</h3><p>The day starts with go-kart travel to the area of interest: a wide-open room containing the sphere, at the center of a larger Backrooms maze. Keep the chamber’s approaches readable so incoming monsters can be recognized and avoided.</p><p>The deposit system and equipment store are in the chamber. The earlier waking-room, antechamber, and safety-door idea can remain part of the starting hub; how it joins the ride is still open.</p></section>
<section class="card"><span class="phase-no">02 / EXCAVATION</span><h3>Seven stages toward the core.</h3><p>Reflective glass → Abandoned Utility Halls → Poolrooms → Abandoned Office → Terror Hotel → Threshold → Core. Begin with a hammer and scaffolding, use an auger for hard materials, research the reality gun for Poolrooms, and acquire a soft-tool pick for the office. Return to the auger in Terror Hotel; solvent research lets the team peel away the final wallpaper and expose the irritated flesh.</p><p>Glass collection provides the first progression goal. Further digging should reveal tools, clues, event doors, enemies, or carcasses. <a href="#egg">Open the Egg dossier ↗</a></p></section>
<section class="card"><span class="phase-no">03 / TEAM ECONOMY</span><h3>Daily gear. Lasting advancement.</h3><p>Resource payouts and store purchases use one shared team cash pool. All items purchased for the day reset each morning. Store and research progression survive day-reset anomalies, so unlocked capabilities can be reached again quickly.</p><p>Cash carryover, purchase authority, baseline equipment, placed scaffolding, and exact world persistence remain open.</p></section>
<section class="card"><span class="phase-no">04 / EVENTS & ENDINGS</span><h3>Some days ask for more than a haul</h3><p>A directive may ask the team to find a door or set up unique equipment. Doors inside the egg lead to puzzle or enemy-evasion event spaces, then exit back into the main hallway.</p><p>Repeated-day scripts, discovering your own dead body, and opportunities spread across days can reveal alternate routes. Secret endings are required; walking out a door or leaving an opportunity behind are ideas to develop.</p></section>
</div>
<section class="workday-strip"><div class="eyebrow">THE DAILY GAMEPLAY LOOP</div><ol><li><b>01</b> Go-kart arrival</li><li><b>02</b> Assignment & daily equipment</li><li><b>03</b> Excavate, deposit & research</li><li><b>04</b> Realify, uncover & enter events</li><li><b>05</b> Return to the hallway & advance</li></ol><p>The collection system feeds shared cash; the chamber store supplies daily gear. Replay-day anomalies may repeat scripts, but they do not erase store or research progression.</p></section>
<section class="card prototype-callout"><div><span class="eyebrow">THE EXCAVATION PATH</span><h3>From the first glass shard to a final choice.</h3><p>Work through an editable player roadmap, the confirmed layer/tool order, research minigames, and possible ending routes.</p></div><a href="#progression" class="button">Player progression ↗</a></section>
<section class="card economy-questions"><span class="eyebrow">OPEN RULES TO SETTLE</span><details open><summary>What resets, and what survives?</summary><p>Daily purchased items reset each morning. Store and research progression survive day-reset anomalies. Unspent cash, scaffolding, excavation changes, and collected clues need separate rules. An anomaly must not force the team to repeat already-completed research.</p></details><details><summary>How does the team recover quickly?</summary><p>Keep previously unlocked tools accessible in the store. A baseline kit, allowance, or reacquisition policy could prevent a broke team from stalling; no option or price is fixed yet.</p></details><details><summary>Who spends the shared cash?</summary><p>Unrestricted spending, a designated buyer, or team approval remain possible. Select a rule that supports the intended cooperation.</p></details></section>`;}
function egg(){return heading('THE EGG / LIVING DESIGN DOSSIER','Glass gives way to something living.','Seven stages. Material-specific tools. A fleshy, irritated core.')+conceptFigure()+`
<div class="notice" style="margin-top:22px"><b>Confirmed sequence:</b> six coverings lead to the fleshy core. The glass-and-tissue artwork above is an earlier material study; it does not depict the intermediate Backrooms layers.</div>
${layerTable()}
<div class="egg-path"><div><span>01 / ACCESS</span><h3>Hammer & scaffolding</h3><p>Shatter reflective glass and build access around the sphere.</p></div><div><span>03 / POOLROOMS</span><h3>Reality-gun research</h3><p>Phase obstructing geometry back into existence before clearing it.</p></div><div><span>06 / THRESHOLD</span><h3>Solvent research</h3><p>Dissolve adhesive bonds and peel away the wallpaper.</p></div><div><span>07 / CORE</span><h3>Expose irritated flesh</h3><p>Beyond the final covering, the living center is revealed.</p></div></div>
<section class="vision-grid" style="margin:24px 0"><article class="card"><span class="tag">THREAT DESIGN</span><h3>Know what is approaching</h3><p>Maze monsters and egg manifestations need unique silhouettes, sound cues, and learnable avoidance rules. A player should be able to recognize the incoming threat and respond before contact.</p></article><article class="card"><span class="tag">DISCOVERY DESIGN</span><h3>Not every emergence is a fight</h3><p>A carcass can be evidence. Your own dead body can make a repeated day feel wrong. Event scripts and returning doors can point toward secret endings without erasing research progress.</p></article></section>
<p class="small muted" style="margin-bottom:20px">Editable development notes below. Enemy names and exact counterplay are proposals; the layer structure and progression-preservation rules reflect the current direction.</p>
<div class="note-grid egg-notes">${Object.entries(eggPrompts).map(([key,p])=>`<section class="card"><label for="egg-${key}">${p[0]}</label><p class="small muted">${p[1]}</p><textarea id="egg-${key}" data-egg="${key}" maxlength="50000">${esc(state.egg[key])}</textarea></section>`).join('')}</div>
<details class="card art-history"><summary>Earlier concept art — design history</summary><p class="small muted">The junk-covered sphere was an earlier visual direction, superseded by the glass-and-tissue study above.</p><img src="assets/crackrooms-sphere-v2.png" loading="lazy" alt="Earlier junk-covered spherical egg concept, retained as design history."></details>`;}
function layerTable(){return `<section class="card" style="margin:24px 0"><div class="eyebrow">CONFIRMED EXCAVATION SEQUENCE</div><h2 style="margin:8px 0 18px">Seven stages to the center</h2><div class="table-scroll"><table><thead><tr><th scope="col">Stage</th><th scope="col">Layer</th><th scope="col">Obstacle and progression</th></tr></thead><tbody>${currentDesign.layers.map((layer,i)=>`<tr><td>${i+1}</td><th scope="row">${esc(layer.title)}</th><td>${esc(layer.obstacle)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function progression(){return heading('PLAYER PROGRESSION / WORKING ROADMAP','From first shift to final exit.','The confirmed layer sequence, followed by your editable player plan. Stages are milestones, not calendar days.','<button class="button" data-action="new-stage">+ Add a stage</button>')+`
<div class="notice"><b>Progression promise:</b> collection and discoveries unlock research; research expands the store. Replay-day anomalies preserve that advancement. Daily items still reset each morning.</div>
${layerTable()}
${sameRoadmap(state.playerRoadmap,currentDesign.roadmap)?'':'<div class="notice"><b>Your saved plan:</b> local edits have been preserved below. The table above shows the current confirmed sequence; revise your plan as needed.</div>'}
<div class="progression-list">${state.playerRoadmap.map((stage,i)=>`<section class="card progression-stage"><div class="section-heading"><div><span class="phase-no">STAGE ${String(i+1).padStart(2,'0')}</span><h2>${esc(stage.title)}</h2></div><button class="button secondary" data-action="edit-stage" data-id="${esc(stage.id)}">Edit stage</button></div><ul>${stage.bullets.map(b=>`<li>${esc(b)}</li>`).join('')}</ul><p class="unlock-note"><b>STORE / TOOL AVAILABILITY</b>${esc(stage.unlock)}</p></section>`).join('')}</div>
<section class="card" style="margin-top:24px"><div class="eyebrow">STORE / TOOL PROGRESSION</div><h2 style="margin:8px 0 18px">When each capability becomes available</h2><p class="small muted">This table follows your editable plan. The confirmed sequence assigns the hammer, hard-tool auger, reality gun, soft-tool pick, and solvent. Prices, acquisition prerequisites, and research minigames remain open.</p><div class="table-scroll"><table><thead><tr><th scope="col">Milestone</th><th scope="col">Availability / research gate</th></tr></thead><tbody>${state.playerRoadmap.map((stage,i)=>`<tr><th scope="row">${i+1}. ${esc(stage.title)}</th><td>${esc(stage.unlock)}</td></tr>`).join('')}</tbody></table></div></section>
<section class="card" style="margin-top:24px"><span class="tag">EVENTS ACROSS THE LAYERS</span><h3>Daily directives, anomalies, and routes out</h3><ul><li>Find an embedded door, complete its puzzle or enemy-evasion event, and exit into the main hallway.</li><li>Some assignments require setting up unique equipment. Place those events within the seven-stage sequence as the story develops.</li><li>Replay previous-day scripts and introduce contradictions such as discovering your own dead body.</li><li>Keep store and research unlocks through anomalies while daily purchased items reset.</li><li>Develop the main conclusion from the core reveal, with secret departures and recurring opportunities across days. Their exact stage placement remains open.</li></ul></section>
<section class="vision-grid" style="margin-top:24px"><article class="card"><span class="tag">RESEARCH TABLE · PROPOSAL</span><h3>A small challenge earns a lasting unlock</h3><ul><li>Bring the relevant sample or event data.</li><li>Develop a minigame for reality-gun research in Poolrooms and solvent research at Threshold. Specific challenges remain proposals.</li><li>Add the tool or shop upgrade to the persistent catalogue.</li><li>Buy its daily instance from the shared cash pool; do not replay completed research after a time anomaly.</li></ul><p>Failure costs, accessibility options, and whether teammates cooperate on the minigame remain open.</p></article><article class="card"><span class="tag">SECRET ENDINGS · REQUIRED</span><h3>Pay attention to chances to leave</h3><ul><li>A main route can resolve a final discovery or exit.</li><li>A door at the right moment may offer a secret departure.</li><li>An opportunity repeated across days may reward an unexpected choice, including leaving something behind.</li><li>Your own body can be a clue to another route.</li></ul><p>These are ending concepts. The final revelation, number of endings, and exact conditions still need writing.</p></article></section>`;}
function stageEditor(id){const stage=state.playerRoadmap.find(s=>s.id===id);openModal(stage?'Edit player progression':'Add a progression stage',field('title','Stage title',stage?.title||'','text','required maxlength="200"')+area('bullets','Player journey — one bullet per line',stage?.bullets.join('\n')||'','Each line becomes a bullet.',true)+area('unlock','Store / tool availability and research gate',stage?.unlock||'','What unlocks here, and what is required?',true),data=>{const title=data.get('title').trim(),bullets=data.get('bullets').split('\n').map(s=>s.trim()).filter(Boolean),unlock=data.get('unlock').trim();if(!title||!bullets.length||!unlock||bullets.length>100){toast('Add a title, 1–100 bullet points, and an unlock description.');return false;}if(!stage&&state.playerRoadmap.length>=100){toast('The roadmap can contain up to 100 stages.');return false;}const next={id:stage?.id||uid(),title,bullets,unlock};if(stage)state.playerRoadmap[state.playerRoadmap.findIndex(s=>s.id===id)]=next;else state.playerRoadmap.push(next);save();render();},'Save stage ↗');}
function journal(){return heading('03 / THE PROCESS','Session log','A record of what you tried, what changed, and what you learned.',addEntryButton)+`<div class="filters"><input type="search" id="entry-search" placeholder="Search your fieldnotes…" aria-label="Search fieldnotes" value="${esc(query)}"><select id="entry-filter" aria-label="Filter by session type">${['all','Build','Design','Research','Playtest'].map(k=>`<option value="${k}" ${kind===k?'selected':''}>${k==='all'?'All session types':k}</option>`).join('')}</select></div><div id="entries-list">${entryList()}</div>`;}
function entryList(){const entries=sortedEntries().filter(e=>(kind==='all'||e.type===kind)&&[e.title,e.body,e.lesson,e.next].join(' ').toLowerCase().includes(query.toLowerCase()));return entries.length?entries.map(e=>entryHTML(e)).join(''):state.entries.length?'<div class="card empty"><h3>No matching entries</h3><p>Try a different search or session type.</p></div>':emptyJournal();}
function roadmap(){return heading('04 / SMALL STEPS, REAL PROGRESS','The first playable expedition.','Development tasks for building the game. The player’s start-to-finish journey is in Player progression.')+`<div class="notice">${done()} of ${state.tasks.length} tasks complete · ${percent()}% of your current roadmap <div class="progress" style="margin-top:9px"><div style="width:${percent()}%"></div></div></div><div class="roadmap">${phases.map((p,i)=>{const tasks=state.tasks.filter(t=>t.phase===i);return `<section class="card"><div class="phase-no">PHASE 0${i+1}</div><div class="phase-head"><h2>${p.name}</h2><span class="tag">${tasks.filter(t=>t.done).length}/${tasks.length}</span></div><p class="phase-desc">${p.description}</p>${tasks.map(taskHTML).join('')}<button class="add-task" data-action="new-task" data-phase="${i}">+ Add a task to this phase</button></section>`}).join('')}</div>`;}
function notebook(){return heading('05 / IDEAS WITH ROOM TO GROW','Design notebook','Keep the big picture close. Every field saves as you write.')+`<div class="note-grid">${Object.entries(prompts).map(([k,p])=>`<section class="card"><label for="note-${k}">${p[0]}</label><p class="small muted">${p[1]}</p><textarea id="note-${k}" data-note="${k}" maxlength="50000" placeholder="${p[2]}">${esc(state.notes[k])}</textarea></section>`).join('')}</div>`;}
function render(){const target=location.hash.slice(1);view=['overview','vision','egg','progression','journal','roadmap','notebook'].includes(target)?target:'overview';$('#project-name').textContent=state.project.name;document.title=state.project.name+' — Build journal';document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.view===view);if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#content').innerHTML=({overview,vision,egg,progression,journal,roadmap,notebook}[view])();$('#footer-count').textContent='FIELDNOTES / '+String(state.entries.length).padStart(3,'0');}
function field(name,label,value='',type='text',extra=''){return `<div class="form-field"><label for="field-${name}">${label}</label><input id="field-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function area(name,label,value='',placeholder='',required=false){return `<div class="form-field"><label for="field-${name}">${label}</label><textarea id="field-${name}" name="${name}" rows="3" maxlength="50000" placeholder="${esc(placeholder)}" ${required?'required':''}>${esc(value)}</textarea></div>`;}
function openModal(title,fields,handler,submit='Save entry ↗'){submitHandler=handler;$('#modal-title').textContent=title;$('#modal-fields').innerHTML=fields;$('#modal-submit').textContent=submit;$('#editor').showModal();}
function entryEditor(id){const e=state.entries.find(e=>e.id===id);openModal(e?'Edit fieldnote':'Log a session',field('title','Give this session a title',e?.title||'','text','required maxlength="200" placeholder="e.g. The hallway finally feels unsettling"')+`<div class="form-row">${field('date','Session date',e?.date||dateValue(),'date','required')}<div class="form-field"><label for="field-type">Session type</label><select name="type" id="field-type">${['Build','Design','Research','Playtest'].map(t=>`<option ${e?.type===t?'selected':''}>${t}</option>`).join('')}</select></div></div>`+field('minutes','Time spent (minutes, optional)',e?.minutes||'','number','min="0" max="1440" step="1" placeholder="45"')+area('body','What did you work on?',e?.body||'','The experiment, the progress, the detour…',true)+area('lesson','What did you learn? (optional)',e?.lesson||'','A discovery worth remembering…')+area('next','Next step (optional)',e?.next||'','One thing to try next time…'),data=>{if(!data.get('title').trim()||!data.get('body').trim()){toast('Add a title and a few words about the session.');return false;}const entry={id:e?.id||uid(),createdAt:e?.createdAt||new Date().toISOString(),title:data.get('title').trim(),date:data.get('date'),type:data.get('type'),minutes:Number(data.get('minutes')||0),body:data.get('body').trim(),lesson:data.get('lesson').trim(),next:data.get('next').trim()};if(e)state.entries[state.entries.findIndex(x=>x.id===e.id)]=entry;else state.entries.push(entry);if(entry.next)state.next=entry.next;save();render();toast(saveError?'Entry kept in this tab. Export a backup.':'Fieldnote saved. Keep building.');});}
function taskEditor(id,phase=0){const t=state.tasks.find(t=>t.id===id);openModal(t?'Edit milestone task':'Add a milestone task',field('title','Task',t?.title||'','text','required maxlength="250" placeholder="A small, concrete next step"')+`<div class="form-field"><label for="field-phase">Phase</label><select id="field-phase" name="phase">${phases.map((p,i)=>`<option value="${i}" ${i===(t?.phase??phase)?'selected':''}>${p.name}</option>`).join('')}</select></div>${t?'<button type="button" class="text-button delete-warning" id="delete-task">Delete this task</button>':''}`,data=>{const title=data.get('title').trim();if(!title){toast('Give your task a name.');return false;}if(t){t.title=title;t.phase=Number(data.get('phase'));}else state.tasks.push({id:uid(),title,phase:Number(data.get('phase')),done:false});save();render();},'Save task ↗');if(t)$('#delete-task').onclick=()=>{confirmAction('Delete this task?',`“${t.title}” will be removed from your roadmap.`,()=>{state.tasks=state.tasks.filter(x=>x.id!==t.id);save();render();});};}
function confirmAction(title,message,action){if($('#editor').open)$('#editor').close();openModal(title,`<p>${esc(message)}</p>`,()=>action(),'Confirm');}
$('#editor-form').onsubmit=e=>{e.preventDefault();if(submitHandler(new FormData(e.currentTarget))!==false)$('#editor').close();};$('#close-modal').onclick=$('#cancel-modal').onclick=()=>$('#editor').close();
$('#content').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.id;switch(b.dataset.action){case'new-stage':stageEditor();break;case'edit-stage':stageEditor(id);break;case'new-entry':entryEditor();break;case'edit-entry':entryEditor(id);break;case'delete-entry':{const entry=state.entries.find(x=>x.id===id);confirmAction('Delete this fieldnote?',`“${entry.title}” will be removed. Export a backup first if you want to keep it.`,()=>{state.entries=state.entries.filter(x=>x.id!==id);save();render();toast('Fieldnote removed.');});break;}case'new-task':taskEditor(null,Number(b.dataset.phase));break;case'edit-task':taskEditor(id);break;}});
$('#content').addEventListener('change',e=>{if(e.target.dataset.task){const task=state.tasks.find(t=>t.id===e.target.dataset.task);task.done=e.target.checked;save();render();const checkbox=document.getElementById('task-'+task.id);if(checkbox)checkbox.focus();}if(e.target.id==='entry-filter'){kind=e.target.value;$('#entries-list').innerHTML=entryList();}});
$('#content').addEventListener('input',e=>{if(e.target.dataset.egg){state.egg[e.target.dataset.egg]=e.target.value;save();}if(e.target.dataset.note){state.notes[e.target.dataset.note]=e.target.value;save();}if(e.target.id==='next-step'){state.next=e.target.value;save();}if(e.target.id==='entry-search'){query=e.target.value;$('#entries-list').innerHTML=entryList();}});
$('#project-settings').onclick=()=>openModal('Make this journal yours',field('name','Project name',state.project.name,'text','required maxlength="80"')+area('tagline','A short description',state.project.tagline),data=>{if(!data.get('name').trim())return false;state.project={name:data.get('name').trim(),tagline:data.get('tagline').trim()};save();render();},'Save project ↗');
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='build-journal-'+dateValue()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Backup exported. Keep it somewhere safe.');};
$('#import').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>10000000){toast('Choose a journal backup smaller than 10 MB.');return;}try{const data=JSON.parse(await file.text());if(!validate(data))throw new Error('Invalid backup');confirmAction('Restore this backup?',`Replace the journal on this device with “${data.project.name}”: ${data.entries.length} sessions and ${data.tasks.length} tasks. Export your current journal first if you want to keep it.`,()=>{state=migrateConcept(data);save();render();toast(saveError?'Restored in this tab. Browser storage unavailable.':'Backup restored.');});}catch(error){toast('This file is not a valid build-journal backup. Your journal is unchanged.');}};
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});
window.addEventListener('storage',e=>{if(e.key!==KEY||!e.newValue)return;try{const incoming=JSON.parse(e.newValue);if(validate(incoming)){state=migrateConcept(incoming);render();toast('Journal updated from another tab.');}}catch{}});
$('#today').textContent=new Date().toLocaleDateString(undefined,{month:'short',day:'2-digit',year:'numeric'}).toUpperCase();render();if(saveError){$('#save-state').textContent='! Could not read saved progress';toast('Saved progress could not be loaded. Restore a backup or export before making changes.');}
